import React,{useCallback,useEffect,useState} from 'react'; import {useSelector} from 'react-redux'; import HorizontalScrollCard from '../../../components/media/HorizontalScrollCard'; import ErrorState from '../../../components/ui/ErrorState'; import Skeleton from '../../../components/ui/Skeleton'; import {getPersonalizedRecommendations} from '../../../api/userDataApi';
const PersonalizedRecommendations=()=>{const user=useSelector(state=>state.auth.user);const[data,setData]=useState(null);const[loading,setLoading]=useState(false);const[error,setError]=useState(null);const load=useCallback(async()=>{if(!user)return;try{setLoading(true);setError(null);const response=await getPersonalizedRecommendations();setData(response.data?.data||null);}catch(requestError){setError(requestError);}finally{setLoading(false);}},[user]);useEffect(()=>{load();},[load]);if(!user)return null;if(loading)return <div className='container mx-auto my-10 px-4 lg:px-10'><Skeleton className='h-64 w-full'/></div>;if(error)return <div className='container mx-auto my-10 px-4 lg:px-10'><ErrorState message='Unable to build your recommendations right now.' onRetry={load}/></div>;if(!data?.results?.length)return null;return <HorizontalScrollCard data={data.results} heading={data.personalized?'Recommended for You':'Popular Picks for You'}/>;}; export default PersonalizedRecommendations;
